56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
65	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
66	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
67	     */
68	    private static final Pattern EMAIL_PATTERN =
69	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        List<String> missingFields = new ArrayList<>();
118	        if (isBlank(ownerFieldsDto.getFirstName())) {
119	            missingFields.add("firstName");
120	        }
121	        if (isBlank(ownerFieldsDto.getLastName())) {
122	            missingFields.add("lastName");
123	        }
124	        if (isBlank(ownerFieldsDto.getAddress())) {
125	            missingFields.add("address");
126	        }
127	        if (isBlank(ownerFieldsDto.getCity())) {
128	            missingFields.add("city");
129	        }
130	        if (isBlank(ownerFieldsDto.getTelephone())) {
131	            missingFields.add("telephone");
132	        }
133	        if (!missingFields.isEmpty()) {
134	            throw new MissingOwnerFieldsException(missingFields);
135	        }
136	        String telephone = ownerFieldsDto.getTelephone().replaceAll("\\D", "");
137	        if (telephone.length() != 10) {
138	            throw new InvalidTelephoneException(
139	                "telephone must contain exactly 10 digits after removing non-digit characters");
140	        }
141	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
142	            .anyMatch(existing -> telephone.equals(normalizeTelephone(existing.getTelephone())));
143	        if (telephoneInUse) {
144	            throw new DuplicateTelephoneException(
145	                "an owner with the same normalized telephone already exists");
146	        }
147	        ownerFieldsDto.setTelephone(telephone);
148	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
149	        HttpHeaders headers = new HttpHeaders();
150	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
151	        this.clinicService.saveOwner(owner);
152	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
153	        headers.setLocation(UriComponentsBuilder.newInstance()
154	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
155	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
161	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
162	        if (currentOwner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        currentOwner.setAddress(ownerFieldsDto.getAddress());
166	        currentOwner.setCity(ownerFieldsDto.getCity());
167	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
168	        currentOwner.setLastName(ownerFieldsDto.getLastName());
169	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
170	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
171	        this.clinicService.saveOwner(currentOwner);
172	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Transactional
177	    @Override
178	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
179	        Owner owner = this.clinicService.findOwnerById(ownerId);
180	        if (owner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        this.clinicService.deleteOwner(owner);
184	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
185	    }
